describe('HeaderList - hierarchy', () => {
  test('instanceof and isPropertyList', () => {
    const hl = new HeaderList(mkReq());
    expect(hl).toBeInstanceOf(ReadOnlyPropertyList);
    expect(ReadOnlyPropertyList.isPropertyList(hl)).toBe(true);
  });
});

describe('HeaderList - read methods (case-insensitive)', () => {
  let hl, req;
  beforeEach(() => {
    req = mkReq({ 'Content-Type': 'application/json', 'X-Token': 'abc' });
    hl = new HeaderList(req);
  });
  test('get', () => {
    expect(hl.get('content-type')).toBe('application/json');
    expect(hl.get('X-TOKEN')).toBe('abc');
    expect(hl.get('missing')).toBeUndefined();
  });
  test('one', () => {
    expect(hl.one('content-type')).toEqual({ key: 'Content-Type', value: 'application/json' });
    expect(hl.one('nope')).toBeUndefined();
  });
  test('all in insertion order + clone', () => {
    const all = hl.all();
    expect(all).toEqual([
      { key: 'Content-Type', value: 'application/json' },
      { key: 'X-Token', value: 'abc' }
    ]);
    all[0].value = 'mutated';
    expect(hl.get('Content-Type')).toBe('application/json');
  });
  test('idx / count', () => {
    expect(hl.idx(1)).toEqual({ key: 'X-Token', value: 'abc' });
    expect(hl.idx(9)).toBeUndefined();
    expect(hl.count()).toBe(2);
  });
  test('indexOf', () => {
    expect(hl.indexOf('x-token')).toBe(1);
    expect(hl.indexOf({ key: 'content-type', value: 'application/json' })).toBe(0);
    expect(hl.indexOf('none')).toBe(-1);
  });
});

describe('HeaderList - search', () => {
