    expect(hl.has('a')).toBe(true);
    expect(hl.has('a', '1')).toBe(true);
    expect(hl.has('a', '9')).toBe(false);
    expect(hl.has({ key: 'b' })).toBe(true);
    expect(hl.has('z')).toBe(false);
  });
  test('find / filter with ctx', () => {
    expect(hl.find((h) => h.key === 'B')).toEqual({ key: 'B', value: '2' });
    const ctx = { want: '1' };
    expect(hl.filter(function (h) { return h.value === this.want; }, ctx)).toEqual([{ key: 'A', value: '1' }]);
  });
});

describe('HeaderList - iteration', () => {
  let hl;
  beforeEach(() => { hl = new HeaderList(mkReq({ 'A': '1', 'B': '2' })); });
  test('forEach', () => {
    const seen = [];
    hl.forEach((h) => seen.push(h.key));
    expect(seen).toEqual(['A', 'B']);
  });
  test('map', () => {
    expect(hl.map((h) => h.key)).toEqual(['A', 'B']);
  });
  test('reduce with and without initial', () => {
    expect(hl.reduce((acc, h) => acc + h.value, '')).toBe('12');
